# Default optimization recipe. Copy to submission/flow/dc_opt.tcl and replace
# this body to explore DC commands, app variables and compile strategies.
# The design is elaborated and the default synthesis constraints are loaded.
# Examples to investigate on the installed DC (check `help` for support):
#   compile_ultra -timing_high_effort_script
#   compile_ultra -retime
#   compile -map_effort high -area_effort high
#   compile_ultra -incremental
# You may change the synthesis target to steer optimization. Final timing is
# independently measured with the benchmark's fixed constraints.
# Keep the external clk/reset/transaction behavior; do not insert clock gating.
ungroup -all -flatten
set_fix_hold [get_clocks clk]
set_max_area 0
set_fix_multiple_port_nets -all -buffer_constants
set_dont_touch_network [get_ports clk]
compile_ultra -area_high_effort_script
compile -incremental_mapping -only_hold_time
# Default RTL optimization. Copy to submission/flow/yosys_opt.ys and replace.
# RTL and library blackboxes have already been read, top is fft64_top.
# You may choose FSM/memory/optimization passes and their order here.
# The wrapper subsequently applies dfflibmap, ABC, and structural export.
# Boolean rewriting such as rewrite/resyn2 belongs in abc_opt.script.
synth -top fft64_top -flatten -noabc
# Default timing-aware ABC technology mapping, matching the Yosys Liberty flow.
# Copy to submission/flow/abc_opt.script and replace the command sequence.
# {D} is replaced by the public builder with -D <requested delay in ps>.
strash;
ifraig; scorr; dc2; dretime; retime {D}; strash;
&get -n; &dch -f; &nf {D}; &put;
buffer; upsize {D}; dnsize {D}; stime -p;
# A resyn2-style alternative Boolean sequence before mapping can include:
# balance; rewrite; refactor; balance; rewrite; rewrite -z; balance;
# refactor -z; rewrite -z; balance;
# Preserve a final Liberty mapping step, e.g. map {D}, or &nf {D}; &put.
====
source [file join [file dirname [info script]] paths.tcl]
set_app_var search_path [concat [get_app_var search_path] [list $WORK [file join $TECH_DIR db]]]
set_app_var link_path [concat [list *] $DBLIST]
read_verilog [file join $WORK mapped.v]
