}
foreach key {FFT_FMAX_MIN_PS FFT_FMAX_MAX_PS FFT_FMAX_TOL_PS FFT_FMAX_ITERATIONS} {
    if {![info exists ::env($key)] || ![string is double -strict $::env($key)] || $::env($key) <= 0} {error "Missing/invalid trusted scan parameter: $key"}
}
