if {$capped} {set failing_json "null"} else {set failing_json [format "%.12f" [expr {$low/1000.0}]]}
puts $f [format {{"status":"CERTIFIED","passing_period_ns":%.12f,"failing_period_ns":%s,"passing_setup_slack_ns":%.12f,"passing_hold_slack_ns":%.12f,"hold_pass":true,"capped_at_minimum_period":%s,"trials":%d}} [expr {$high/1000.0}] $failing_json [expr {[lindex $final 1]/1000.0}] [expr {[lindex $final 2]/1000.0}] [expr {$capped ? "true" : "false"}] $trial_count]
close $f
close $trace
} task_error]} {
    puts stderr "TASK_FATAL: $task_error"
    exit 1
}
exit 0

"""Original fixed-point models and independent test families for this task."""
import numpy as np

N=64
F=15

def reference(x):
    x=np.asarray(x);return np.fft.fft((x[...,0]+1j*x[...,1])/(1<<F),axis=-1)

def quality(x,z):
    ref=reference(x);z=np.asarray(z);pred=(z[...,0]+1j*z[...,1])/(1<<F)
    sse=np.sum(abs(pred-ref)**2,axis=-1);energy=np.sum(abs(ref)**2,axis=-1)
    nz=energy>0;nmse=np.zeros_like(energy);nmse[nz]=sse[nz]/energy[nz]
    q=-10*np.log10(np.maximum(nmse[nz],1e-300))
    return dict(frames=len(x),minimum_frame_sqnr_db=float(q.min())if len(q)else None,
                pooled_sqnr_db=float(-10*np.log10(max(float(sse.sum()/energy.sum()),1e-300)))if energy.sum()else None,
                worst_frame_nmse=float(nmse.max()),zero_frame_exact=bool(np.all(z[~nz]==0)),
                failed_frames=np.flatnonzero(nz&(nmse>1e-5)).tolist(),
                feasible=bool(np.all(nmse[nz]<=1e-5)and np.all(z[~nz]==0)))

def make_frames(seed=20261116,scale=1):
    rng=np.random.default_rng(seed);out=[];labels=[]
    def add(name,a):
        a=np.rint(np.asarray(a)*(1<<F)).astype(np.int64)
        if a.ndim==2:a=a[None]
        assert a.min()>=-16384 and a.max()<=16384
        rms=np.sqrt(np.mean(np.sum((a/(1<<F))**2,axis=-1),axis=-1))
        keep=(rms>=1/32)|(rms==0)
        for z in a[keep]:out.append(z);labels.append(name)
    for amp in [.0625,.125,.5]:add('uniform_'+str(amp),rng.uniform(-amp,amp,(8*scale,N,2)))
    for sig in [.03125,.125,.3]:add('gaussian_'+str(sig),np.clip(rng.normal(0,sig,(8*scale,N,2)),-.5,.5))
    t=np.arange(N)
    for k in [0,1,7,15,16,31,32,63,3.25,17.5]:
        for amp in [.0625,.25,.5]:
            zz=amp*np.exp(2j*np.pi*(k*t/N+rng.uniform(0,1)))
            add('tone',np.stack([zz.real,zz.imag],-1))
    for p in [0,1,17,63]:
        for z in [[.25,0],[0,-.25],[.5,.5]]:
            a=np.zeros((N,2));a[p]=z;add('impulse',a)
    for _ in range(8*scale):
        f=np.zeros(N,dtype=complex);idx=np.r_[np.arange(1,13),np.arange(N-12,N)]
        f[idx]=rng.choice([-3,-1,1,3],len(idx))+1j*rng.choice([-3,-1,1,3],len(idx))
        a=np.fft.ifft(f);a*=.45/max(abs(a.real).max(),abs(a.imag).max())
        add('QAM_OFDM',np.stack([a.real,a.imag],-1))
        a=np.sum([rng.uniform(.03,.15)*np.exp(2j*np.pi*(rng.uniform(0,N)*t/N+rng.uniform(0,1)))for j in range(4)],axis=0)
        a*=.45/max(abs(a.real).max(),abs(a.imag).max());add('multitone',np.stack([a.real,a.imag],-1))
    add('DC_corner',np.full((N,2),.5));add('negative_DC_corner',np.full((N,2),-.5))
    add('Nyquist',np.column_stack([.5*(-1.)**t,.5*(-1.)**t]))
    # Explicit near-minimum-RMS rounding boundaries: an agent cannot rely on
    # random quantization errors cancelling inside an otherwise biased FFT.
    for raw in [1025,1026,1028,1030,1031,-1025,-1026,-1028,-1030]:
        a=np.zeros((N,2));a[:,0]=raw/(1<<F);add('quantization_boundary_DC',a)
        a[:,0]*=(-1.)**t;add('quantization_boundary_Nyquist',a)
    # Both I/Q components near the smallest valid complex RMS, with changing
    # signs. DC-only witnesses cannot reveal combined input/coefficient error.
    for raw in [725,726,727,730,1031]:
        a=rng.choice([-raw,raw],(8*scale,N,2))/(1<<F)
        add('complex_sign_quantization_boundary_'+str(raw),a)
    add('zero',np.zeros((N,2)))
    return np.asarray(out),labels


def evaluation_frames(seed, random_frames=1024):
    """Independent nonzero 64-point frames, followed by directed cases.

    Count means FRAMES, never FFT length. Rejection happens after quantization
    so every scored nonzero frame satisfies the declared complex RMS domain.
    """
    if type(random_frames)is not int or random_frames<1024:
        raise ValueError('Numerical evaluation needs at least 1024 independent random frames')
    rng=np.random.default_rng(seed);frames=[];labels=[]
    while len(frames)<random_frames:
        family=int(rng.integers(0,6))
        if family==0:a=rng.uniform(-.5,.5,(64,2))
        elif family==1:a=rng.uniform(-.0625,.0625,(64,2))
        elif family==2:a=np.clip(rng.normal(0,.125,(64,2)),-.5,.5)
        elif family==3:a=np.clip(rng.normal(0,.03125,(64,2)),-.5,.5)
        elif family==4:a=np.clip(rng.normal(0,.3,(64,2)),-.5,.5)
        else:
            raw=int(rng.choice([725,726,727,730,1031]));a=rng.choice([-raw,raw],(64,2))/32768
        x=np.rint(a*32768).astype(np.int64)
        if np.sqrt(np.mean(np.sum((x/32768)**2,axis=-1)))<1/32:continue
        frames.append(x);labels.append('independent_random_'+str(family))
    directed,names=make_frames(seed^0x6a09e667,1)
    for x,label in zip(directed,names):
        if label in {'tone','impulse','DC_corner','negative_DC_corner','Nyquist','zero'}or label.startswith('quantization_boundary'):
            frames.append(x);labels.append('directed_'+label)
    # Every integer-frequency bin, including extrema and low-amplitude tones.
    t=np.arange(64)
    for k in range(64):
        for amplitude in [.0625,.5]:
            z=amplitude*np.exp(2j*np.pi*(k*t/64+rng.uniform(0,1)))
            frames.append(np.rint(np.column_stack([z.real,z.imag])*32768).astype(np.int64))
            labels.append('directed_frequency_sweep')
    out=np.asarray(frames,dtype=np.int64)
    assert out.shape==(len(out),64,2) and out.min()>=-16384 and out.max()<=16384
    return out,labels


def quality_union(*qualities):
    """Hard SQNR uses the minimum over applicable, successfully decoded tests."""
    items=[q for q in qualities if q]
    minima=[q['minimum_frame_sqnr_db']for q in items if q.get('minimum_frame_sqnr_db')is not None]
    return dict(frames=sum(q['frames']for q in items),
                minimum_frame_sqnr_db=min(minima)if minima else None,
                worst_frame_nmse=max(q['worst_frame_nmse']for q in items),
                zero_frame_exact=all(q['zero_frame_exact']for q in items),
                feasible=all(q['feasible']for q in items),
                aggregation='minimum SQNR and maximum NMSE, never average frame dB',
                failed_frames=[dict(test=i,indices=q.get('failed_frames',[]))for i,q in enumerate(items)if not q['feasible']])
#!/usr/bin/env python3
"""Check output integer codes; RTL, protocol and PPA use run_preview.sh."""
import argparse
import json
from pathlib import Path
import sys
import numpy as np
from model import quality
from numeric_io import input_frames, samples

def check(inputs, outputs):
    names, frames = input_frames(inputs)
    entries = outputs.get('frames')
    if not isinstance(entries, list) or len(entries) != len(names):
        raise ValueError('Output frames are missing or extra')
    table = {}
    for item in entries:
        if item['id'] in table:
            raise ValueError('Duplicate output frame ID')
        table[item['id']] = samples(item.get('outputs_iq'), -(1 << 23), (1 << 23)-1)
    if set(table) != set(names):
        raise ValueError('Output frame IDs differ from the input IDs')
    result = quality(frames, np.asarray([table[name] for name in names]))
    result['failed_ids'] = [names[i] for i in result['failed_frames']]
    return result

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--inputs', required=True)
    parser.add_argument('--outputs', required=True)
    args = parser.parse_args()
    try:
        result = check(json.loads(Path(args.inputs).read_text()), json.loads(Path(args.outputs).read_text()))
    except (ValueError, KeyError, TypeError) as exc:
        print(json.dumps(dict(feasible=False, failure=str(exc))))
        return 1
    print(json.dumps(result, indent=2, allow_nan=False))
    return 0 if result['feasible'] else 1

if __name__ == '__main__':
    sys.exit(main())
#!/usr/bin/env python3
"""Produce small deterministic PUBLIC FFT64 development input frames.

Not a final graded dataset and not a substitute for hidden low-RMS/sign tests.
"""
import argparse, json
from pathlib import Path
import numpy as np

N=64
SCALE=1<<15
LIM=1<<14

def q(z):
    return np.clip(np.rint(z*SCALE), -LIM, LIM).astype(np.int64)

def valid_or_raise(c):
    codes=q(c.real)+1j*q(c.imag)
    x=codes/SCALE
    rms=np.sqrt(np.mean(np.abs(x)**2))
    if rms<1/32 and rms>0:
        raise ValueError(f'Generated nonzero frame below RMS limit: {rms}')
    return np.stack([q(c.real),q(c.imag)],axis=-1).tolist()

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument('--out',default='public_data/dev_inputs.json')
    ap.add_argument('--seed',type=int,default=20261118)
    args=ap.parse_args()
    r=np.random.default_rng(args.seed)
    t=np.arange(N)
    cases={}
    cases['zero']=np.zeros(N,dtype=complex)
    cases['impulse']=np.eye(1,N,0).reshape(-1).astype(complex)*0.25
    cases['dc_complex']=np.full(N,0.105-0.08j)
    cases['nyquist_complex']=((-1.0)**t)*(0.08+0.11j)
    cases['tone_7']=0.21*np.exp(2j*np.pi*7*t/N)
    cases['two_tones']=0.14*np.exp(2j*np.pi*3*t/N)+0.11j*np.exp(2j*np.pi*21*t/N)
    cases['low_rms_mixed_sign']=0.035*np.exp(2j*np.pi*9*t/N)+0.012*np.exp(-2j*np.pi*5*t/N)
    for i in range(12):
        z=(r.uniform(-0.22,0.22,N)+1j*r.uniform(-0.22,0.22,N))
        cases[f'uniform_{i:02d}']=z
    for i in range(8):
        z=r.normal(0,0.13,N)+1j*r.normal(0,0.13,N)
        cases[f'gaussian_{i:02d}']=np.clip(z.real,-0.5,0.5)+1j*np.clip(z.imag,-0.5,0.5)
    for i in range(8):
        z=(2*r.integers(0,2,N)-1)+1j*(2*r.integers(0,2,N)-1)
        cases[f'qpsk_{i:02d}']=0.18*z
    out={'schema':'fft64_inputs','reference':'float64_fft_of_same_quantized_input','frames':[]}
    for name,z in cases.items():
        out['frames'].append({'id':name,'inputs_iq':valid_or_raise(z)})
    p=Path(args.out);p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(out,indent=2)+'\n')
    print('Wrote',len(out['frames']),'public input frames to',p)
if __name__=='__main__':main()
"""Validate the public JSON sample format and the legal FFT input domain."""
import numpy as np

def samples(value, low, high):
    if not isinstance(value, list) or len(value) != 64:
        raise ValueError('Expected 64 [real_integer, imaginary_integer] samples')
    for pair in value:
        if not isinstance(pair, list) or len(pair) != 2:
            raise ValueError('Expected pairs of integer codes')
        if any(type(x) is not int or not low <= x <= high for x in pair):
            raise ValueError('Sample is not an integer code in the permitted range')
    return np.asarray(value, dtype=np.int64)

def input_frames(document):
    frames = document.get('frames')
    if not isinstance(frames, list) or not frames:
        raise ValueError('Expected a nonempty frames list')
    names, arrays = [], []
    for frame in frames:
        name = frame['id']
        if not isinstance(name, str) or name in names:
            raise ValueError('Frame IDs must be distinct strings')
        codes = samples(frame['inputs_iq'], -16384, 16384)
        energy = float(np.mean(np.sum((codes/32768.0)**2, axis=-1)))
        if energy != 0 and energy < (1/32)**2:
            raise ValueError('Nonzero frame is below the specified complex RMS')
        names.append(name)
        arrays.append(codes)
    return names, np.asarray(arrays)

"""Exported commercial backend. Execution status is separate from local evidence."""
from pathlib import Path
import math,os,re,time,subprocess,shutil,hashlib,json
from common import ROOT,TECH,COMB,SEQ,run,read,save,sha,lock,flow_identity,InfrastructureError,CacheIdentityError,tool_failure
from toolchain import activate,find_tool

def preflight(require_db=True):
 tools=activate()
 cmds=['vcs','dc_shell','pt_shell']
 return dict(commands={x:tools[x]for x in cmds},libraries={str(x):x.exists()for x in [COMB,SEQ]},compiled_db={str(x):x.exists()for x in [TECH/'db/comb_rvt_tt.db',TECH/'db/seq_rvt_tt.db']},ready=all(tools[x]for x in cmds)and all(x.exists()for x in [COMB,SEQ])and(not require_db or all(x.exists()for x in [TECH/'db/comb_rvt_tt.db',TECH/'db/seq_rvt_tt.db'])))

def check_log(path):
 # A Synopsys batch process can exit zero after reporting script errors.
 errors=re.findall(r'^\s*(?:Error:|Fatal:|TASK_FATAL)[^\n]*',path.read_text(),re.M)
 if errors:raise tool_failure(str(path)+'\n'+'\n'.join(errors[:8]))

def checked_metrics(path,kind):
 try:metrics=read(path)
 except (OSError,ValueError) as exc:raise InfrastructureError('Missing or malformed '+kind+' metrics: '+str(path))from exc
 fields=['area_um2','register_area_um2']if kind=='DC'else['worst_setup_slack_ns','worst_hold_slack_ns','clock_period_ns']
 if not isinstance(metrics,dict):raise InfrastructureError('Invalid '+kind+' metrics object: '+str(path))
 for field in fields:
  value=metrics.get(field)
  if type(value)not in (int,float)or not math.isfinite(value):
   raise InfrastructureError('Invalid '+kind+' metric '+field+': '+str(path))
 if kind=='DC':
  if(metrics['area_um2']<=0 or not 0<=metrics['register_area_um2']<=metrics['area_um2']
     or type(metrics.get('cells'))is not int or metrics['cells']<=0):
   raise InfrastructureError('Invalid DC mapped area/count: '+str(path))
 elif metrics['clock_period_ns']<=0:
  raise InfrastructureError('Invalid PT required period: '+str(path))
 return metrics

def mapping_identity():
 files=['flow/synth_dc.tcl','flow/constraints.sdc','flow/timing_pt.tcl','flow/paths.tcl','flow/templates/dc_opt.tcl']
 libraries=[COMB,SEQ,TECH/'db/comb_rvt_tt.db',TECH/'db/seq_rvt_tt.db']
 tools={name:find_tool(name)for name in ['dc_shell','pt_shell']}
 if not all(tools.values()):raise EnvironmentError('DC/PT mapping environment is unavailable')
 data=dict(files={f:sha(ROOT/f)for f in files},libraries={p.name:sha(p)for p in libraries},
           tools={name:dict(path=p,sha256=sha(p))for name,p in tools.items()},clock_period_ns=10.0,independent_import_measurement=True)
 return hashlib.sha256(json.dumps(data,sort_keys=True).encode()).hexdigest()

def measure(source,outdir,formal=False,implementation=None):
 destination=Path(outdir).resolve()
 physical=mapping_identity()
 cache=os.environ.get('FFT_PHYSICAL_CACHE_DIR')
 if not cache:return _measure(source,destination,formal,physical,implementation)
