 d=Path(outdir).resolve();d.mkdir(parents=True,exist_ok=True)
 check=preflight();save(d/'preflight.json',check)
 if not check['ready']:raise EnvironmentError('COMMERCIAL_ENVIRONMENT_NOT_READY: '+str(d/'preflight.json'))
