"""Clock-scan certification on one fixed mapped ASIC netlist."""
from pathlib import Path
import csv
import hashlib
import json
import math
import os
import shutil
from common import ROOT,run,save,read,sha,lock
from scoring import profile_policy,POLICY_SHA256
from toolchain import find_tool


def validate_trials(endpoint,trials,settings):
    if endpoint.get('status')!='CERTIFIED' or not endpoint.get('hold_pass'):
        raise EnvironmentError('No passing setup/hold frequency endpoint')
    passing=endpoint['passing_period_ns'];failing=endpoint.get('failing_period_ns')
    for row in trials:
        for key in ['period_ns','actual_clock_period_ns','setup_slack_ns','hold_slack_ns']:
            if not math.isfinite(row[key]):raise EnvironmentError('Nonfinite STA scan measurement')
        if abs(row['period_ns']-row['actual_clock_period_ns'])>1e-6:
            raise EnvironmentError('STA scan did not apply the requested clock')
    point=[r for r in trials if abs(r['period_ns']-passing)<1e-8 and r['pass']]
    if not point or min(point[-1]['setup_slack_ns'],point[-1]['hold_slack_ns'])<0:
        raise EnvironmentError('Passing clock was not measured successfully')
    if endpoint.get('capped_at_minimum_period'):
        if failing is not None or abs(passing-settings['minimum_period_ns'])>1e-8:
            raise EnvironmentError('Invalid scan-cap endpoint')
    else:
        if(failing is None or failing>=passing
           or passing-failing>settings['resolution_ns']+1e-9):
            raise EnvironmentError('Invalid passing/failing frequency bracket')
        bad=[r for r in trials if abs(r['period_ns']-failing)<1e-8 and r['setup_slack_ns']<0]
        if not bad:raise EnvironmentError('Failing endpoint has no measured setup violation')
    if len(trials)!=endpoint.get('trials'):raise EnvironmentError('Incomplete frequency scan trace')


def certify(asic,backend='commercial'):
    if backend=='local':
        from local_frequency import certify_local
        return certify_local(asic)
    from commercial import check_log
    asic=Path(asic).resolve()
    settings=profile_policy('architecture')['fmax_scan']
    pt=find_tool('pt_shell')
    if not pt:raise EnvironmentError('PrimeTime is required for official frequency certification')
    identity=dict(mapped_sha256=sha(asic/'mapped.v'),script_sha256=sha(ROOT/'flow/fmax_pt.tcl'),
                  pt_path=pt,pt_sha256=sha(pt),scan=settings,policy_sha256=POLICY_SHA256,
                  mapping_signature=read(asic/'signature.json'))
    key=hashlib.sha256(json.dumps(identity,sort_keys=True).encode()).hexdigest()[:24]
    work=asic/'frequency_certificates'/key
    with lock(work/'lock'):
        if(work/'certificate.json').exists():return read(work/'certificate.json'),work
        shutil.copy2(asic/'mapped.v',work/'mapped.v')
        save(work/'identity.json',identity)
        keys=['FFT_WORK','FFT_TASK_ROOT','FFT_FMAX_MIN_PS','FFT_FMAX_MAX_PS','FFT_FMAX_TOL_PS','FFT_FMAX_ITERATIONS']
        previous={k:os.environ.get(k)for k in keys}
        os.environ.update(FFT_WORK=str(work),FFT_TASK_ROOT=str(ROOT),
                          FFT_FMAX_MIN_PS=str(settings['minimum_period_ns']*1000),
                          FFT_FMAX_MAX_PS=str(settings['maximum_period_ns']*1000),
                          FFT_FMAX_TOL_PS=str(settings['resolution_ns']*1000),
                          FFT_FMAX_ITERATIONS=str(settings['maximum_iterations']))
        try:
            run(['pt_shell','-f',ROOT/'flow/fmax_pt.tcl'],work/'fmax.log',600,cwd=work)
            check_log(work/'fmax.log')
            endpoint=read(work/'fmax_scan/endpoint.json')
            with(work/'fmax_scan/trials.csv').open(newline='')as stream:
                trials=[dict(trial=int(r['trial']),period_ns=float(r['period_ns']),
                             actual_clock_period_ns=float(r['actual_clock_period_ns']),
                             setup_slack_ns=float(r['setup_slack_ns']),hold_slack_ns=float(r['hold_slack_ns']),
                             **{'pass':r['pass']=='1'})for r in csv.DictReader(stream)]
            validate_trials(endpoint,trials,settings)
            check=(work/'fmax_scan/check_at_passing.rpt').read_text()
            if __import__('re').search(r'(?im)^\s*Warning:.*(?:unconstrained|no[_ ]clock|no[_ ]input[_ ]delay|no[_ ]output[_ ]delay)',check):
                raise EnvironmentError('Frequency scan has unconstrained paths')
            certificate=dict(endpoint,**identity,trial_trace_sha256=sha(work/'fmax_scan/trials.csv'),
                             certified_frequency_MHz=1000/endpoint['passing_period_ns'],
                             measurement='PrimeTime setup/hold passing endpoint on a fixed mapped netlist; pre-layout',
                             certificate_directory=str(work))
            save(work/'certificate.json',certificate)
            return certificate,work
        finally:
            for k,v in previous.items():
                if v is None:os.environ.pop(k,None)
                else:os.environ[k]=v
"""Mapped implementations produced by agent-controlled public optimization flows."""
from pathlib import Path
import hashlib
import json
import re
import shutil
import tempfile
from common import COMB,SEQ,DesignInvalidError,sha,read,save

ARTIFACTS=('mapped.v','manifest.json')
RECIPES=('dc_opt.tcl','yosys_opt.ys','abc_opt.script','pnr_opt.tcl')


def validate_structural(text):
    """Accept one flattened structural top; library cell behavior comes from the kit."""
    code=re.sub(r'/\*.*?\*/|//[^\n]*','',text,flags=re.S)
    code=re.sub(r'\(\*.*?\*\)','',code,flags=re.S)
    code=re.sub(r'\\[^\s]+','escaped_identifier',code)
    modules=re.findall(r'\bmodule\s+([A-Za-z_][A-Za-z_0-9]*)',code)
    if modules!=['fft64_top'] or len(re.findall(r'\bendmodule\b',code))!=1:
        raise DesignInvalidError('implementation/mapped.v must contain one flattened fft64_top, without library model definitions')
    if re.search(r'[`$#]|\b(?:always(?:_ff|_comb|_latch)?|initial|final|function|task|generate|primitive|specify|force|release|DPI|real|shortreal|defparam)\b',code):
        raise DesignInvalidError('Mapped implementation must be structural standard cells and net aliases, without behavioral code or directives')
    return text


def load(submission,rtl_sha256):
    directory=Path(submission)/'implementation'
    if not directory.exists():return None
    if not directory.resolve().is_relative_to(Path(submission).resolve()):raise DesignInvalidError('Implementation must be inside the submission')
    if not all((directory/name).is_file()for name in ARTIFACTS):
        raise DesignInvalidError('implementation/ requires both mapped.v and manifest.json; build or remove the incomplete export')
    if any(not(directory/name).resolve().is_relative_to(Path(submission).resolve())for name in ARTIFACTS):raise DesignInvalidError('Implementation files must be inside the submission')
    try:manifest=read(directory/'manifest.json')
    except (OSError,ValueError)as exc:raise DesignInvalidError('Invalid implementation manifest: '+str(exc))from exc
    if not isinstance(manifest,dict):raise DesignInvalidError('Implementation manifest must be an object')
    expected=dict(rtl_sha256=rtl_sha256,mapped_sha256=sha(directory/'mapped.v'),
                  libraries_sha256={p.name:sha(p)for p in [COMB,SEQ]})
    for key,value in expected.items():
        if manifest.get(key)!=value:raise DesignInvalidError('Mapped implementation '+key+' does not match the submitted RTL/netlist or fixed ASAP7 library; rebuild it')
    producer=manifest.get('producer',{})
    if not isinstance(producer,dict):raise DesignInvalidError('Implementation producer must be an object')
    declared=producer.get('custom_files_sha256',{})
    if not isinstance(declared,dict):raise DesignInvalidError('Recipe provenance must be an object')
    for name,value in declared.items():
        path=Path(submission)/'flow'/name
        if not path.resolve().is_relative_to((Path(submission)/'flow').resolve()):raise DesignInvalidError('Invalid recipe provenance path')
        if not path.is_file()or sha(path)!=value:raise DesignInvalidError('Optimization recipe changed after export; rebuild the implementation')
    validate_structural((directory/'mapped.v').read_text())
    return dict(path=str((directory/'mapped.v').resolve()),mapped_sha256=expected['mapped_sha256'],
                manifest_sha256=sha(directory/'manifest.json'),producer=manifest.get('producer'),
                libraries_sha256=expected['libraries_sha256'],rtl_sha256=rtl_sha256)


def export_artifacts(source,submission,backup):
    source=Path(source);destination=Path(submission)/'implementation';backup=Path(backup)
    if not all((source/name).is_file()for name in ARTIFACTS):raise ValueError('Build did not produce a complete implementation')
    if destination.exists():
        if backup.exists():raise ValueError('Export backup already exists; choose a new build output')
        shutil.copytree(destination,backup)
    with tempfile.TemporaryDirectory(prefix='.implementation_',dir=destination.parent)as temporary:
        staged=Path(temporary)/'ready';shutil.copytree(source,staged)
        previous=Path(temporary)/'previous'
        if destination.exists():destination.rename(previous)
        try:staged.replace(destination)
        except BaseException:
            if previous.exists():previous.replace(destination)
            raise
    return destination
"""Public optimization worker: editable native recipes, structural artifact export."""
from pathlib import Path
import argparse
import json
import os
import shutil
import sys
import time
from common import ROOT,TECH,COMB,SEQ,run,save,sha,read,lock,CacheIdentityError
from toolchain import activate,find_tool,prepare
from implementation import validate_structural,export_artifacts


def initialize(submission):
    directory=Path(submission)/'flow';directory.mkdir(parents=True,exist_ok=True)
    for name in ['dc_opt.tcl','yosys_opt.ys','abc_opt.script','pnr_opt.tcl']:
        target=directory/name
        if not target.exists():shutil.copy2(ROOT/'flow/templates'/name,target)
    return directory


def q(path):
    return '"'+str(path).replace('\\','\\\\').replace('"','\\"')+'"'


def build(submission,outdir,backend='commercial',abc_delay_ps=10000,timeout=1800):
    from evaluate import assemble
    activate();submission=Path(submission).resolve();out=Path(outdir).resolve();out.mkdir(parents=True,exist_ok=True)
    source,info=assemble(submission,include_implementation=False)
    names=['dc_opt.tcl']if backend=='commercial'else['yosys_opt.ys','abc_opt.script']
    tools=['dc_shell']if backend=='commercial'else['yosys','abc']
    selected={name:find_tool(name)for name in tools}
    if not all(selected.values()):raise EnvironmentError('Required build tools missing: '+str(selected))
    recipes={name:(submission/'flow'/name if (submission/'flow'/name).is_file()else ROOT/'flow/templates'/name)for name in names}
    custom={str(p.relative_to(submission/'flow')):sha(p)for p in sorted((submission/'flow').rglob('*'))if p.is_file()}if(submission/'flow').is_dir()else{}
    identity=dict(rtl_sha256=info['source_sha256'],backend=backend,abc_delay_ps=abc_delay_ps,
        recipes={name:sha(path)for name,path in recipes.items()},custom_files=custom,
        libraries={p.name:sha(p)for p in [COMB,SEQ]},
        tools={name:dict(path=path,sha256=sha(path))for name,path in selected.items()},
        worker_sha256=sha(__file__),dc_driver_sha256=sha(ROOT/'flow/build_dc.tcl'))
    with lock(out/'build.lock'):
        signature=out/'build_identity.json'
        if signature.exists()and read(signature)!=identity:raise CacheIdentityError('Build inputs changed; choose a new build output directory')
        save(signature,identity)
        artifact=out/'implementation';manifest=artifact/'manifest.json'
        if manifest.exists()and(artifact/'mapped.v').exists():
            cached=read(manifest)
            if cached.get('mapped_sha256')==sha(artifact/'mapped.v'):
                return dict(status='BUILT',reused=True,implementation=str(artifact),manifest=cached)
        started=time.monotonic();work=out/'build';work.mkdir(exist_ok=True)
        (work/'source.sv').write_text(source)
        recipe_dir=work/'flow'
        if(submission/'flow').is_dir():shutil.copytree(submission/'flow',recipe_dir,dirs_exist_ok=True)
        recipe_dir.mkdir(exist_ok=True)
        for name,path in recipes.items():shutil.copy2(path,recipe_dir/name)
        old={key:os.environ.get(key)for key in ['FFT_WORK','FFT_TASK_ROOT','FFT_TECH_DIR','FFT_AGENT_DC_RECIPE','FFT_MAPPED_OUTPUT']}
        os.environ.update(FFT_WORK=str(work),FFT_TASK_ROOT=str(ROOT),FFT_TECH_DIR=str(TECH),
            FFT_AGENT_DC_RECIPE=str(recipe_dir/'dc_opt.tcl'),FFT_MAPPED_OUTPUT=str(work/'mapped.v'))
        try:
            if backend=='commercial':
                run(['dc_shell','-f',ROOT/'flow/build_dc.tcl'],work/'dc_build.log',timeout,cwd=work)
                from commercial import check_log
                check_log(work/'dc_build.log')
            else:
                abc_text='\n'.join(line for line in (recipe_dir/'abc_opt.script').read_text().splitlines()if not line.lstrip().startswith('#'))+'\n'
                abc_text=abc_text.replace('{D}','-D '+format(abc_delay_ps,'g'))
                (work/'abc_opt.script').write_text(abc_text)
                (work/'abc.constr').write_text('set_driving_cell BUFx2_ASAP7_75t_R\nset_load 1\n')
                ys=f'read_liberty -lib {q(COMB)}\nread_liberty -lib {q(SEQ)}\nread_verilog -sv {q(work/"source.sv")}\n'
                ys+=(recipe_dir/'yosys_opt.ys').read_text()+'\n'
                ys+=f'dfflibmap -liberty {q(SEQ)}\nabc -exe {q(selected["abc"])} -liberty {q(COMB)} -constr abc.constr -D {abc_delay_ps} -script abc_opt.script\n'
                ys+=f'flatten\nclean\ncheck\nwrite_verilog -noattr -noexpr {q(work/"mapped.v")}\nstat\n'
                (work/'build.ys').write_text(ys)
                run(['yosys','-Q','-T','-s',work/'build.ys'],work/'yosys_build.log',timeout,cwd=work)
            mapped=validate_structural((work/'mapped.v').read_text())
            artifact.mkdir(exist_ok=True);(artifact/'mapped.v').write_text(mapped)
            provenance=dict(rtl_sha256=info['source_sha256'],mapped_sha256=sha(artifact/'mapped.v'),
                libraries_sha256={p.name:sha(p)for p in [COMB,SEQ]},
                producer=dict(backend=backend,tools=identity['tools'],recipe_sha256=identity['recipes'],
                              custom_files_sha256=custom,abc_delay_ps=abc_delay_ps),
                build_seconds=time.monotonic()-started,
                evaluation='Area/timing are measured independently; producer reports are not scores')
            shutil.copytree(recipe_dir,artifact/'recipes',dirs_exist_ok=True)
            save(manifest,provenance)
            result=dict(status='BUILT',reused=False,implementation=str(artifact),manifest=provenance)
            save(out/'build_result.json',result);return result
        finally:
            for key,value in old.items():
                if value is None:os.environ.pop(key,None)
                else:os.environ[key]=value


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('submission');parser.add_argument('--out')
    parser.add_argument('--backend',choices=['local','commercial'],default='local')
    parser.add_argument('--init-flow',action='store_true');parser.add_argument('--export',action='store_true')
    parser.add_argument('--abc-delay-ps',type=float,default=10000)
    parser.add_argument('--timeout',type=int,default=1800)
    args=parser.parse_args(argv)
    if args.abc_delay_ps<=0 or args.timeout<=0:parser.error('Delay target and timeout must be positive')
    if args.init_flow:
        print(initialize(args.submission));return 0
    if not args.out:parser.error('--out is required')
    if args.backend=='commercial':
        environment=prepare('commercial',allow_build=False)
        if not environment['ready']:raise EnvironmentError('Commercial build environment is not ready: '+str(environment))
    result=build(args.submission,args.out,args.backend,args.abc_delay_ps,args.timeout)
    if args.export:result['exported_to']=str(export_artifacts(result['implementation'],args.submission,Path(args.out)/'export_backup'))
    print(json.dumps(result,indent=2));return 0


if __name__=='__main__':sys.exit(main())

"""Frozen independent area and architecture/throughput scoring profiles."""
from pathlib import Path
import hashlib
import json
import math

POLICY_PATH=Path(__file__).resolve().parents[1]/'profiles/policy.json'
POLICY=json.loads(POLICY_PATH.read_text())
POLICY_SHA256=hashlib.sha256(POLICY_PATH.read_bytes()).hexdigest()
SCORING_ID='fft64_quant'


def measurement_context(result):
    """Comparable protocol and runtime identities, excluding the candidate RTL."""
    from cache import digest,runtime_identity
    from common import ROOT,sha
    runtime=runtime_identity(result['backend'])
    platform={k:runtime[k]for k in ['tools','libraries','drivers','flow_scripts','python_version','python_sha256','numpy_version']}
    protocol=dict(specification_sha256=sha(ROOT/'SPEC.json'),generator_sha256=sha(ROOT/'tools/model.py'),
                  seed=result['seed'],scale=result['scale'],audience=result['audience'])
    return dict(protocol_fingerprint=digest(protocol),measurement_platform_fingerprint=digest(platform))


def evaluation_outcome(result):
    status=result.get('status')
    if status in {'UNSCORED_INFRASTRUCTURE','ENVIRONMENT_ERROR','FAILED'}:
        return 'UNSCORED_INFRASTRUCTURE'
    if status in {'DESIGN_INVALID','QUALITY_FAILED','THROUGHPUT_FAILED'}:
        return 'DESIGN_INVALID'
    if status=='COMPLETE':
        if hardware_feasible(result):return 'FEASIBLE'
        # Missing evidence is not a demonstrated design violation.
        flags=[result.get('quality',{}).get('feasible'),result.get('protocol_pass'),
               result.get('mapped_simulation_pass'),result.get('ppa',{}).get('timing_pass')]
        if False in flags or result.get('ppa',{}).get('formal_status')=='FAILED':return 'DESIGN_INVALID'
        return 'INCOMPLETE'
    return 'INCOMPLETE'


def profile_policy(profile):
    if profile not in POLICY['profiles']:raise ValueError('Unknown scoring profile: '+str(profile))
    return POLICY['profiles'][profile]


def public_parameters():
    """All arithmetic score parameters are public and independent of inputs."""
    values=dict(POLICY['public_normalization'])
    for name,value in values.items():positive(value,name)
    if not values['area_half_credit_um2']>values['area_ideal_um2']:
        raise ValueError('Area half-credit anchor must exceed the ideal area')
    if not values['throughput_ideal_ffts_per_second']>values['throughput_min_ffts_per_second']:
        raise ValueError('Ideal throughput must exceed mandatory throughput')
    if not values['first_output_max_cycles']>values['first_output_ideal_cycles']:
        raise ValueError('Latency ceiling must exceed ideal latency')
    return values


def component_scores(measured,profile):
    """Smooth area feedback and logarithmic throughput over the measured range."""
    p=public_parameters();area=positive(measured['area_um2'],'area')
    ideal=p['area_ideal_um2'];half=p['area_half_credit_um2']
    area_score=1.0 if area<=ideal else (half-ideal)/(area+half-2*ideal)
    values=dict(area=area_score,throughput=0.0,latency=0.0)
    if profile=='architecture':
        t=positive(measured['effective_throughput_ffts_per_second'],'effective throughput')
        values['throughput']=normalized(math.log(t),math.log(p['throughput_min_ffts_per_second']),
                                       math.log(p['throughput_ideal_ffts_per_second']),False)
        values['latency']=normalized(measured['first_output_cycles'],p['first_output_max_cycles'],
                                     p['first_output_ideal_cycles'],True)
    return values


def hardware_feasible(result):
    passed=bool(result.get('status')=='COMPLETE'
                and result.get('quality',{}).get('feasible',False)
                and result.get('protocol_pass',False)
                and result.get('mapped_simulation_pass',False)
                and result.get('ppa',{}).get('timing_pass',False)
                and result.get('ppa',{}).get('formal_status')!='FAILED')
    if result.get('profile','area')=='architecture':
        passed=passed and result.get('throughput_check',{}).get('status')=='PASS'
    if passed:
        try:performance(result)
        except (ValueError,TypeError,KeyError):passed=False
    return bool(passed)


def positive(value,name):
    if type(value)not in(int,float)or not math.isfinite(value)or value<=0:
        raise ValueError('Missing or invalid measured '+name)
    return value


def performance(result,profile=None):
    profile=profile or result.get('profile','area');profile_policy(profile)
    ppa=result.get('ppa',{});lat=result.get('latency',{})
    area=positive(ppa.get('area_um2'),'area')
    clock=positive(ppa.get('clock_period_ns',lat.get('clock_period_ns')),'common clock period')
    first=lat.get('first_output_latency_cycles',[])
    first_cycles=positive(max(first)if first else None,'first-output cycles')
    out=dict(area_um2=area,first_output_cycles=first_cycles,first_output_latency_ns=first_cycles*clock,
             target_clock_period_ns=clock,base_frame_II_cycles=lat.get('offered_frame_II'),
             measured_frequency_in_score=False)
    if profile=='area':return out
    stream=result.get('throughput_check',{})
    if stream.get('status')!='PASS' or not stream.get('mapped_pass'):
        raise ValueError('Continuous-frame RTL and mapped verification is required')
    interval=positive(stream.get('verified_frame_ii_cycles'),'verified stream frame II')
    certificate=ppa.get('fmax_certificate',{})
    if(certificate.get('status')!='CERTIFIED' or not certificate.get('hold_pass')
       or certificate.get('mapped_sha256')!=ppa.get('mapped_sha256')):
        raise ValueError('A matching passing clock-scan certificate is required; fixed-clock slack is insufficient')
    period=positive(certificate.get('passing_period_ns'),'certified passing clock period')
    resolution=profile_policy('architecture')['fmax_scan']['resolution_ns']
    if certificate.get('capped_at_minimum_period'):
        if abs(period-profile_policy('architecture')['fmax_scan']['minimum_period_ns'])>1e-8:
            raise ValueError('Invalid frequency scan cap')
    else:
        failing=positive(certificate.get('failing_period_ns'),'certified failing clock period')
        if failing>=period:raise ValueError('Invalid frequency scan bracket')
        if period-failing>resolution+1e-9:raise ValueError('Frequency scan bracket is wider than the frozen resolution')
    dense_first=stream.get('first_output_latency_cycles',[])
    if dense_first:first_cycles=max(first_cycles,max(dense_first))
    return dict(out,first_output_cycles=first_cycles,first_output_latency_ns=first_cycles*clock,
                certified_period_ns=period,certified_setup_fmax_MHz=1000/period,
                verified_frame_II_cycles=interval,effective_throughput_ffts_per_second=1e9/(interval*period),
                effective_throughput_samples_per_second=64e9/(interval*period),
                first_output_latency_at_certified_clock_ns=first_cycles*period)


def make_calibration(results,profile='area',**metadata):
    policy=profile_policy(profile)
    if not results or not all(hardware_feasible(r)for r in results.values()):
        raise ValueError('All accurate baselines must pass the selected profile')
    if len({(r.get('backend'),r.get('flow_id'))for r in results.values()})!=1:
        raise ValueError('Accurate baselines must share backend and measurement flow')
    contexts=[r.get('measurement_context')for r in results.values()]
    if any(context!=contexts[0]for context in contexts):
        raise ValueError('Accurate baselines must share the measured protocol and runtime')
    if contexts[0] is not None:metadata['measurement_context']=contexts[0]
    measured={name:performance(r,profile)for name,r in results.items()}
    best_area=min(measured,key=lambda n:measured[n]['area_um2'])
    area_best=measured[best_area]['area_um2'];p=public_parameters()
    first_result=next(iter(results.values()))
    references=dict(area_um2=p['area_half_credit_um2']);targets=dict(area_um2=p['area_ideal_um2'])
    sources=dict(area_reference='public_half_credit_anchor',area_target='public_ideal_anchor')
    if profile=='architecture':
        clock=POLICY['shared_spec']['clock_period_ns']
        references.update(throughput_ffts_per_second=p['throughput_min_ffts_per_second'],
                          first_output_latency_ns=p['first_output_max_cycles']*clock)
        targets.update(throughput_ffts_per_second=p['throughput_ideal_ffts_per_second'],
                       first_output_latency_ns=p['first_output_ideal_cycles']*clock)
        sources.update(throughput_reference='public_mandatory_service',throughput_target='public_scan_ceiling',
                       latency_reference='public_mandatory_deadline',latency_target='public_serial_input_bound')
    return dict(metadata,backend=first_result['backend'],flow_id=first_result['flow_id'],profile=profile,
                scoring_policy_id=SCORING_ID,policy_sha256=POLICY_SHA256,weights=policy['weights'],
                references=references,targets=targets,anchor_sources=sources,baseline_performance=measured,
                reference_area_um2=references['area_um2'],reference_design='public_physical_anchors',
                accurate_reference_area_um2=area_best,normalization_parameters=p,
                normalization='public fixed rational-area, logarithmic-throughput and linear-latency functions; accurate measurements validate the platform')


def normalized(value,reference,target,lower_is_better):
    span=(reference-target)if lower_is_better else(target-reference)
    if span<0:raise ValueError('Normalization target is in the wrong direction')
    if span==0:return float(value<=target)if lower_is_better else float(value>=target)
    gain=(reference-value)if lower_is_better else(value-reference)
    return float(min(1,max(0,gain/span)))


def score_result(result,calibration=None):
    profile=result.get('profile','area');profile_policy(profile)
    feasible=hardware_feasible(result)
    outcome=evaluation_outcome(result)
    grade=dict(resolved=feasible,feasible=feasible,score=0.0,
               score_valid=outcome=='DESIGN_INVALID',evaluation_outcome=outcome,
               scoring_policy_id=SCORING_ID,profile=profile,policy_sha256=POLICY_SHA256,area_ratio=None,
               scoring_scope='public_preview'if result.get('audience')=='public'else'hidden_evaluation',
               official_score=bool(outcome=='DESIGN_INVALID'and result.get('audience')=='hidden'))
    if outcome=='UNSCORED_INFRASTRUCTURE':return dict(grade,reason='UNSCORED_INFRASTRUCTURE: '+result.get('failure','Measurement could not be completed.'))
    if result.get('status')=='QUICK_CHECK_PASSED':return dict(grade,reason='INCOMPLETE: Public numerical and sustained protocol checks passed; ASIC/capacity scoring was not requested.')
    if outcome=='INCOMPLETE':return dict(grade,reason='INCOMPLETE: Evaluation evidence is not complete; no final score.')
    if not feasible:return dict(grade,reason='DESIGN_INVALID: A required numerical, protocol, timing or RTL/mapped check failed.')
    try:measured=performance(result,profile)
    except ValueError as exc:return dict(grade,reason=str(exc))
    policy=profile_policy(profile)
    preview=result.get('audience')=='public'
    if not calibration and not preview:
        return dict(grade,performance=measured,reason='UNSCORED_INFRASTRUCTURE: Hidden grading requires matching platform/protocol validation calibration; public previews use the published score parameters directly.')
    if calibration:
        expected=dict(backend=result.get('backend'),flow_id=result.get('flow_id'),profile=profile,
                      scoring_policy_id=SCORING_ID,policy_sha256=POLICY_SHA256)
        if any(calibration.get(k)!=v for k,v in expected.items()):
            return dict(grade,reason='UNSCORED_INFRASTRUCTURE: Calibration belongs to another profile, policy, backend or flow; recalibrate.')
        if calibration.get('measurement_context')!=result.get('measurement_context'):
            return dict(grade,reason='UNSCORED_INFRASTRUCTURE: Calibration protocol, numerical runtime or tool identity does not match.')
        if calibration.get('weights')!=policy['weights'] or calibration.get('normalization_parameters')!=public_parameters():
            return dict(grade,reason='UNSCORED_INFRASTRUCTURE: Calibration does not match the published weights and numeric normalization.')
    components=component_scores(measured,profile)
    score=sum(policy['weights'][k]*v for k,v in components.items())
    return dict(grade,score=float(score),score_valid=True,area_ratio=measured['area_um2']/public_parameters()['area_half_credit_um2'],
                components=components,weighted_components={k:policy['weights'][k]*v for k,v in components.items()},
                weights=policy['weights'],performance=measured,normalization_parameters=public_parameters(),
                scoring_scope='public_preview'if preview else'hidden_evaluation',official_score=not preview,
                reason=('PUBLIC_PREVIEW: All public hardware checks passed; component scores use the published fixed numeric targets. Final acceptance requires independent hidden evaluation.'if preview else
                        'All required profile specifications passed; continuous hardware score has no pass threshold.'))
"""Public SSH bridge for a sibling Synopsys mount and port.txt; host stdlib only."""
from pathlib import Path
import argparse
import contextlib
import datetime
import hashlib
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
import tempfile
import time
import uuid

REPO = Path(__file__).resolve().parents[2]
LIBRARIES = ['ASAP7_RVT_TT_nldm_NO_FAHA.lib', 'ASAP7_SEQ_RVT_TT_nldm_220123.lib', 'cells_sim.v']
PUBLIC_FILES = ['SPEC.json', 'requirements.txt', 'runtime.sh', 'setup.sh', 'run_preview.sh']
PUBLIC_DIRS = ['tools', 'flow', 'profiles']
IGNORE = shutil.ignore_patterns('.git', '__pycache__', '*.pyc', 'runs', '.eval_state',
                               'obj', 'csrc', 'simv', 'simv.daidir', '*.log', '*.log.json', 'attempts')


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True).encode()).hexdigest()


def save(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name+'.'+str(os.getpid())+'.tmp')
    temporary.write_text(json.dumps(value, indent=2)+'\n'); temporary.replace(path)


def file_hashes(directory):
    return {str(p.relative_to(directory)): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in sorted(Path(directory).rglob('*')) if p.is_file() and not any(IGNORE(str(directory), [part]) for part in p.relative_to(directory).parts)}


class Layout:
    def __init__(self, repo=REPO, port_file=None, shared=None, port=None, mount='/mnt/mydata', host='root@localhost'):
        self.repo = Path(repo).resolve()
        self.port_file = Path(port_file).resolve() if port_file else self.repo.parent/'port.txt'
        self.shared = Path(shared).resolve() if shared else self.repo.parent/'Synopsys'
        self.mount = str(Path(mount))
        self.host = host
        if not self.mount.startswith('/'):
            raise ValueError('The container mount must be an absolute path')
        if port is None:
            try: text = self.port_file.read_text().strip()
            except OSError as exc:
                raise ValueError('Cannot read '+str(self.port_file)+'; create it with the container SSH port.') from exc
            if not re.fullmatch(r'[0-9]+', text):
                raise ValueError('port.txt must contain one integer SSH port')
            port = int(text)
        if type(port) is not int or not 1 <= port <= 65535:
            raise ValueError('SSH port must be between 1 and 65535')
        self.port = port

    def remote(self, path):
        path = Path(path).resolve()
        try: relative = path.relative_to(self.shared)
        except ValueError as exc: raise ValueError('Path is outside the shared mount: '+str(path)) from exc
        return str(Path(self.mount)/relative)

    def metadata(self):
        return dict(ssh_host=self.host, ssh_port=self.port, port_file=str(self.port_file),
                    shared_directory=str(self.shared), container_mount=self.mount)


class Connection:
    def __init__(self, layout):
        self.layout = layout
        key = digest(dict(host=layout.host, port=layout.port, shared=str(layout.shared)))[:12]
        self.state = Path(tempfile.gettempdir())/('f64_'+str(os.getuid())+'_'+key)
        self.state.mkdir(mode=0o700, exist_ok=True)
        self.state.chmod(0o700)

    def run(self, script, capture=False, log=None):
        if not shutil.which('ssh'): raise RuntimeError('OpenSSH client is required on the host')
        with tempfile.TemporaryDirectory(prefix='askpass_', dir=self.state) as temporary:
            helper = Path(temporary)/'askpass.sh'
            helper.write_text('#!/bin/sh\nprintf \'%s\\n\' "$FFT_SSH_PASSWORD"\n'); helper.chmod(0o700)
            env = dict(os.environ)
            env.update(SSH_ASKPASS=str(helper), SSH_ASKPASS_REQUIRE='force',
                       DISPLAY=env.get('DISPLAY') or ':0',
                       FFT_SSH_PASSWORD=env.get('FFT_SSH_PASSWORD', 'passwd'))
            argv = ['ssh', '-o', 'StrictHostKeyChecking=accept-new', '-o',
                    'UserKnownHostsFile='+str(self.state/'known_hosts'), '-o', 'ConnectTimeout=10',
                    '-o', 'NumberOfPasswordPrompts=1', '-o', 'ControlMaster=auto',
                    '-o', 'ControlPersist=10m', '-o', 'ControlPath='+str(self.state/'socket'),
                    '-o', 'ServerAliveInterval=30', '-o', 'ServerAliveCountMax=2',
                    '-p', str(self.layout.port), self.layout.host, 'bash -lc '+shlex.quote(script)]
            if log is None:
                return subprocess.run(argv, stdin=subprocess.DEVNULL, env=env, start_new_session=True,
                                      text=True, capture_output=capture)
            with Path(log).open('w') as stream:
                process=subprocess.Popen(argv,stdin=subprocess.DEVNULL,env=env,start_new_session=True,
                                         text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
                for line in process.stdout:
                    stream.write(line);stream.flush();print(line,end='',flush=True)
                return subprocess.CompletedProcess(argv,process.wait())

    def handshake(self):
        if not self.layout.shared.is_dir():
            raise ValueError('Shared directory does not exist: '+str(self.layout.shared))
        directory = self.layout.shared/'.fft64/handshakes'/uuid.uuid4().hex
        directory.mkdir(parents=True)
        token = uuid.uuid4().hex
        (directory/'host.txt').write_text(token)
        host_file = shlex.quote(self.layout.remote(directory/'host.txt'))
        reply = shlex.quote(self.layout.remote(directory/'container.txt'))
        script = ('set -e; test "$(cat '+host_file+')" = '+shlex.quote(token)+'; '
                  'printf %s '+shlex.quote(token)+' > '+reply+'; '
                  'if [ "$(id -u)" = 0 ]; then chown '+str(os.getuid())+':'+str(os.getgid())+' '+reply+'; fi')
        result = self.run(script, capture=True)
        if result.returncode:
            raise RuntimeError('SSH/shared-mount check failed:\n'+result.stdout+result.stderr+
                               '\nExpected '+str(self.layout.shared)+' mounted at '+self.layout.mount)
        if not (directory/'container.txt').is_file() or (directory/'container.txt').read_text() != token:
            raise RuntimeError('The SSH container is not using the expected writable shared mount')
        return dict(ssh=True, shared_read=True, shared_write=True)


